import React, { useState, useEffect } from "react";
import { Table, Alert, Layout, Card, Pagination } from "antd";
import axios from "axios";
import Navbar from "../Online Broadband Ordering/Navbar";
import Footer from "../Online Broadband Ordering/Footer";
import Sidebar from "../Customer Portal/Sidebar";
import { apiUrl } from "../utils/utils";

const LogsPage = () => {
  const [logs, setLogs] = useState([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");
  const [pagination, setPagination] = useState({
    current: 1,
    pageSize: 10,
    total: 0,
  });

  const fetchLogs = async (page = 1, limit = 10) => {
    setLoading(true);
    setError("");
    try {
      const response = await axios.get(
        `${apiUrl()}orderstatus/logs?page=${page}&limit=${limit}`
      );
      if (response.data?.status) {
        setLogs(response.data.data || []);
        setPagination({
          current: response.data.pagination.page,
          pageSize: response.data.pagination.limit,
          total: response.data.pagination.total,
        });
      } else {
        setError("Failed to load logs.");
      }
    } catch (err) {
      setError("API error while fetching logs.");
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchLogs(pagination.current, pagination.pageSize);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const handlePageChange = (page, pageSize) => {
    fetchLogs(page, pageSize);
  };

  const columns = [
    { title: "ID", dataIndex: "id", key: "id", fixed: "left", width: 80 },
    { title: "Product ID", dataIndex: "product_id", key: "product_id" },
    { title: "Action", dataIndex: "action", key: "action" },
    {
      title: "Status",
      dataIndex: "status",
      key: "status",
      render: (val) =>
        val === "success" ? (
          <span className="text-green-600 font-semibold">Success</span>
        ) : (
          <span className="text-red-600 font-semibold">Error</span>
        ),
    },
    {
      title: "Error Message",
      dataIndex: "error_message",
      key: "error_message",
      render: (msg) => msg || "-",
    },
    {
      title: "Created At",
      dataIndex: "created_at",
      key: "created_at",
      render: (date) => new Date(date).toLocaleString(),
    },
    {
      title: "Request Payload",
      dataIndex: "request_payload",
      key: "request_payload",
      render: (payload) => (
        <pre className="bg-gray-100 p-2 rounded text-xs max-w-xs overflow-auto">
          {payload ? JSON.stringify(JSON.parse(payload), null, 2) : "-"}
        </pre>
      ),
    },
    {
      title: "Response Payload",
      dataIndex: "response_payload",
      key: "response_payload",
      render: (payload) =>
        payload ? (
          <pre className="bg-gray-100 p-2 rounded text-xs max-w-xs overflow-auto">
            {JSON.stringify(payload, null, 2)}
          </pre>
        ) : (
          "No response"
        ),
    },
  ];

  return (
    <Layout className="min-h-screen">
      <div className="flex flex-col min-h-screen">
        <Navbar />
        <Layout>
          <Layout hasSider>
            <Sidebar />
            <div className="flex-grow flex flex-col items-center p-4">
              {loading && (
                <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50">
                  <div className="w-16 h-16 border-4 border-gray-200 border-t-[#5664F5] rounded-full animate-spin"></div>
                </div>
              )}

              <div className="w-full max-w-6xl">
                <h1 className="text-xl font-semibold text-left mb-6">
                  Order Status Logs
                </h1>

                {error && (
                  <Alert
                    message={error}
                    type="error"
                    showIcon
                    className="mb-4"
                  />
                )}

                <Card className="shadow-md mb-6">
                  <Table
                    columns={columns}
                    dataSource={logs}
                    rowKey="id"
                    pagination={false} 
                    scroll={{ x: 1500 }}
                  />
                </Card>
              </div>

              {/* Custom pagination outside card, centered */}
              <div className="mt-4">
                <Pagination
                  current={pagination.current}
                  pageSize={pagination.pageSize}
                  total={pagination.total}
                  onChange={handlePageChange}
                  showSizeChanger={false}
                />
              </div>
            </div>
          </Layout>
        </Layout>
        <Footer />
      </div>
    </Layout>
  );
};

export default LogsPage;
